// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract ArtworkCertificate {
    struct Certificate {
        string artistName;
        string artworkName;
        string artworkFeature;
        string artworkImage; // Can store IPFS hash or URL
        string artworkCategory;
        uint256 date;
        bool isValid;
    }

    mapping(bytes32 => Certificate) private certificates;

    event CertificateIssued(
        bytes32 indexed certificateHash,
        string artistName,
        string artworkName,
        string artworkFeature,
        string artworkImage,
        string artworkCategory,
        uint256 date
    );

    function issueCertificate(
        string memory _artistName,
        string memory _artworkName,
        string memory _artworkFeature,
        string memory _artworkImage,
        string memory _artworkCategory
    ) public returns (bytes32) {
        bytes32 certificateHash = keccak256(
            abi.encodePacked(_artistName, _artworkName, _artworkFeature, _artworkImage, _artworkCategory, block.timestamp)
        );
        certificates[certificateHash] = Certificate(
            _artistName,
            _artworkName,
            _artworkFeature,
            _artworkImage,
            _artworkCategory,
            block.timestamp,
            true
        );

        emit CertificateIssued(
            certificateHash,
            _artistName,
            _artworkName,
            _artworkFeature,
            _artworkImage,
            _artworkCategory,
            block.timestamp
        );
        return certificateHash;
    }

    function getCertificateByHash(bytes32 _certificateHash) public view returns (
        string memory, string memory, string memory, string memory, string memory, uint256, bool
    ) {
        require(certificates[_certificateHash].isValid, "Certificate not found");
        Certificate memory cert = certificates[_certificateHash];
        return (cert.artistName, cert.artworkName, cert.artworkFeature, cert.artworkImage, cert.artworkCategory, cert.date, cert.isValid);
    }
}
